  ret = netlib_set_ipv4addr(FIREYEYE_NET_DEVNAME, &addr);
  syslog(LOG_INFO, "FireEye net: set ip -> %d\n", ret);

  if (inet_pton(AF_INET, FIREYEYE_NET_NETMASK, &addr) == 1)
    {
