  static const uint8_t mac[6] = FIREYEYE_NET_MAC;
  netlib_setmacaddr(FIREYEYE_NET_DEVNAME, mac);

  ret = fireeye_net_apply_addresses();
  if (ret < 0)
    {
      return ret;
    }

  ret = netlib_ifup(FIREYEYE_NET_DEVNAME);
